content.content:
1	:root {
2	  --bg-color: #f8fafc;
3	  --surface-color: #ffffff;
4	  --text-primary: #1e293b;
5	  --text-secondary: #64748b;
6	  --accent-color: #0f172a; /* Slate 900 for a very professional, sharp look */
7	  --accent-light: #334155;
8	  --highlight-color: #2563eb; /* Blue 600 for interactive elements */
9	  --font-main: "Roboto", sans-serif;
10	  --font-serif: "Roboto Slab", serif;
11	
12	  /* Component System */
13	  --text-size-section-title: 2.5rem;
14	  --text-size-h3: 1.5rem;
15	  --radius-sm: 12px;
16	  --radius-md: 16px;
17	  --radius-lg: 24px;
18	  --radius-full: 9999px;
19	
20	  --spacing-card: 40px;
21	
22	  /* Color System */
23	  --border-subtle: rgba(0, 0, 0, 0.05);
24	
25	  --shadow-sm: 0 1px 3px 0 rgba(0, 0, 0, 0.1), 0 1px 2px 0 rgba(0, 0, 0, 0.06);
26	  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.05);
27	  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05);
28	  --shadow-xl: 0 20px 25px -5px rgba(0, 0, 0, 0.1), 0 10px 10px -5px rgba(0, 0, 0, 0.04);
29	  --shadow-primary: 0 4px 10px rgba(37, 99, 235, 0.2);
30	  --shadow-primary-hover: 0 10px 20px rgba(37, 99, 235, 0.3);
31	
32	  --text-muted: #94a3b8;
33	  --icon-muted: #e2e8f0;
34	
35	  --bg-subtle: #f1f5f9;
36	  --bg-glass: rgba(255, 255, 255, 0.9);
37	  --highlight-hover: #1d4ed8;
38	  
39	  --shadow-navbar: 0 4px 20px rgba(0, 0, 0, 0.08);
40	}
41	
42	html {
43	  scroll-behavior: smooth;
44	}
45	
46	body {
47	  background-color: var(--bg-color);
48	  color: var(--text-primary);
49	  font-family: var(--font-main);
50	  margin: 0;
51	  padding: 0;
52	  line-height: 1.6;
53	  display: flex;
54	  flex-direction: column;
55	  min-height: 100vh;
56	  align-items: center;
57	}
58	
59	.container {
60	  max-width: 1000px;
61	  width: 100%;
62	  padding: 115px 20px 60px;
63	  box-sizing: border-box;
64	}
65	
66	/* Header / Hero */
67	.hero {
68	  text-align: center;
69	  margin-bottom: 80px;
70	  animation: fadeIn 0.8s ease-out;
71	}
72	
73	@keyframes fadeIn {
74	  from {
75	    opacity: 0;
76	    transform: translateY(20px);
77	  }
78	  to {
79	    opacity: 1;
80	    transform: translateY(0);
81	  }
82	}
83	
84	.headshot {
85	  width: 160px;
86	  height: 160px;
87	  border-radius: 50%;
88	  object-fit: cover;
89	  margin-bottom: 30px;
90	  box-shadow: var(--shadow-xl);
91	  border: 4px solid var(--surface-color);
92	  transition: transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
93	}
94	
95	.headshot:hover {
96	  transform: scale(1.05) rotate(2deg);
97	}
98	
99	h1.author {
100	  font-family: var(--font-serif);
101	  font-size: clamp(1.55rem, 6.8vw, 3rem);
102	  font-weight: 700;
103	  color: var(--text-primary);
104	  margin: 0 0 12px 0;
105	  letter-spacing: -0.02em;
106	}
107	
108	h3.intro {
109	  font-family: var(--font-main);
110	  font-size: clamp(0.95rem, 3vw, 1.25rem);
111	  font-weight: 500;
112	  color: var(--accent-light);
113	  margin: 0 0 30px 0;
114	  letter-spacing: 0.08em;
115	}
116	
117	.description {
118	  font-size: clamp(0.95rem, 3.4vw, 1.125rem);
119	  color: var(--text-secondary);
120	  max-width: 680px;
121	  margin: 0 auto 40px auto;
122	  font-weight: 300;
123	}
124	
125	.generative-ai {
126	  color: var(--highlight-color);
127	  font-weight: 500;
128	}
129	
130	/* CTA & Animation */
131	.cta-section {
132	  margin: 50px 0;
133	  display: flex;
134	  flex-direction: column;
135	  align-items: center;
136	  gap: 30px;
137	}
138	
139	.typewriter-container {
140	  font-family: var(--font-serif);
141	  font-size: clamp(1.3rem, 5.2vw, 2rem);
142	  font-weight: 300;
143	  color: var(--text-primary);
144	  min-height: 1.5em; /* Prevent layout shift */
145	  display: flex;
146	  align-items: center;
147	  justify-content: center;
148	  flex-wrap: wrap;
149	  gap: 0.5rem;
150	}
151	
152	.typewriter-text {
153	  color: var(--highlight-color);
154	  font-weight: 600;
155	  border-right: 3px solid var(--highlight-color);
156	  white-space: pre;
157	  padding-right: 4px; /* Fix cursor cutting through text */
158	  animation: blink-caret 0.8s step-end infinite;
159	}
160	
161	@keyframes blink-caret {
162	  from,
163	  to {
164	    border-color: transparent;
165	  }
166	  50% {
167	    border-color: var(--highlight-color);
168	  }
169	}
170	
171	.cta-button {
172	  display: inline-flex;
173	  align-items: center;
174	  gap: 12px;
175	  background-color: var(
176	    --highlight-color
177	  ); /* Royal Blue instead of dark slate */
178	  color: white;
179	  padding: 16px 36px;
